use crate::income::IncomeCadence;

/// Nominal days between receipts at each cadence — what "overdue" is measured against.
///
/// Fractional for the two that do not divide a month evenly. Rounding semimonthly to 15 and monthly
/// to 30 would make every source drift a little early into "lapsed" over a long history.
pub(crate) fn cadence_days(c: IncomeCadence) -> Option<f64> {
    match c {
        IncomeCadence::Weekly => Some(7.0),
        IncomeCadence::Biweekly => Some(14.0),
        IncomeCadence::Semimonthly => Some(15.2),
        IncomeCadence::Monthly => Some(30.4),
        IncomeCadence::Irregular => None,
    }
}
